/**
 * The shipped catalog.
 *
 * Import the card list from the `./data` subpath so core users do not pay for
 * it:
 *
 * ```ts
 * import { cards, sets, catalogVersion } from "@dierkens.dev/ptcg-decklist-tools/data";
 * ```
 *
 * Cards are generated by `pnpm run catalog` from a pinned public TCGdex dump;
 * archetypes are snapshotted by `pnpm run archetypes` from Limitless. The small
 * set and alias data ship in the core through `shipped.ts`.
 */

import cardsJson from "./data/cards.json" with { type: "json" };

import {
  shippedArchetypes,
  shippedCatalogVersion,
  shippedSets,
} from "./shipped.js";
import type { Catalog, CatalogCard } from "./types.js";

export type { Catalog, CatalogArchetype, CatalogCard, CatalogSet } from "./types.js";
export const archetypes = shippedArchetypes;
export const sets = shippedSets;

/** The build date of this catalog, `YYYY-MM-DD`. Store it beside a hash. */
export const catalogVersion: string = shippedCatalogVersion;

/** Every Live-addressable printing, in set and collector-number order. */
export const cards: readonly CatalogCard[] = cardsJson as readonly CatalogCard[];

/** The whole catalog in one object, ready for `normalizeDecklist(parsed, { catalog })`. */
export const catalog: Catalog = { cards, sets, catalogVersion };
